void MG2_ItemSprites::Initialize()
{
    if (!bEnabled || !MG2_SpritePatcher::bAllowReplacements)
    {
        return;
    }

    if (!MG2_SpritePatcher::AddPatch(nMedicalSymbolImageEntry, nOriginalMedicalSymbolHash, anMedicalSymbolImage.data(), anMedicalSymbolImage.size()))
    {
        spdlog::error("MG2: Item Sprites : Could not register the medical restoration.");
    }
    else
    {
        spdlog::info("MG2: Item Sprites : Medical patch registered.");
    }

    for (const PaletteColour& stColour : astCigaretteColours)
    {
        if (!MG2_SpritePatcher::AddPalettePatch(nCigarettePaletteEntry, stColour.nIndex, stColour.nRgb))
        {
            spdlog::error("MG2: Item Sprites : Could not register cigarette palette.");
            return;
        }
    }
    if (!MG2_SpritePatcher::AddPatch(nCigaretteImageEntry, nOriginalCigaretteHash, anCigaretteImage.data(), anCigaretteImage.size()))
    {
        spdlog::error("MG2: Item Sprites : Could not register cigarette restoration.");
    }
    else
    {
        spdlog::info("MG2: Item Sprites : Cigarette image and palette patches registered.");
    }
}
